export const LOCALE_VERSION = '2026.1';
const AR_DIG = '٠١٢٣٤٥٦٧٨٩', AR_EXT = '۰۱۲۳۴۵۶۷۸۹';
export function digits(str, ns) {
  str = String(str);
  if (ns === 'arab') return str.replace(/[0-9]/g, d => AR_DIG[+d]);
  if (ns === 'arabext') return str.replace(/[0-9]/g, d => AR_EXT[+d]);
  return str;
}
export function resolveNS(lang, setting) {
  if (setting && setting !== 'auto') return setting;
  const L = LOCALES[lang] || LOCALES.en;
  return L.digits;
}
export function fmtNum(n, lang, nsSetting, dec = 0, group = false) {
  let s = Number(n).toFixed(dec);
  if (group) s = s.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return digits(s, resolveNS(lang, nsSetting));
}
