export const CAL_LANGS = Object.keys(LOCALES);
export const UI_LANGS = ['en', 'ar', 'fr', 'tr', 'ur', 'id', 'ms'];

export function fmtDateParts(parts, lang, cal, style, nsSetting) {
  const L = LOCALES[lang] || LOCALES.en, ns = resolveNS(lang, nsSetting);
  const months = cal === 'hijri' ? L.hijri.months : L.greg.months;
  const patKey = cal === 'hijri' ? (style === 'full' ? 'hFull' : style === 'long' ? 'hLong' : 'medium') : style;
  const pat = L.pat[patKey] || L.pat.long;
  const s = pat
    .replace('{wd}', L.greg.wd[parts.wd])
    .replace('{d}', digits(parts.d, ns))
    .replace('{mo}', months[parts.m - 1])
    .replace('{ms}', L.greg.short[parts.m - 1])
    .replace('{m}', digits(parts.m, ns))
    .replace('{y}', digits(parts.y, ns));
  return s;
}
export function fmtClock(p, lang, format, seconds, nsSetting) {
  const L = LOCALES[lang] || LOCALES.en, ns = resolveNS(lang, nsSetting);
  const fmt = format === 'auto' ? L.clockDefault : format;
  let h = p.h, suffix = '';
  if (fmt === '12') { suffix = ' ' + L.ampm[h < 12 ? 0 : 1]; h = h % 12 || 12; }
  const mm = String(p.mi).padStart(2, '0'), ss = String(p.s).padStart(2, '0');
  return digits(`${h}:${mm}${seconds ? ':' + ss : ''}`, ns) + suffix;
}

